def parse_generic_fallback(path, lines, lang):
    # For unhandled languages, return empty (no tags)
    # But for some like HTML, JSON, we could implement simple?
    if lang == "HTML":
        tags=[]
        for idx, raw in enumerate(lines):
            lineno=idx+1
            line=raw.rstrip("\r\n")
            # Very simplified: extract <title>T</title> -> T as j? and <h1 id="a">Hi</h1> -> Hi as h? and id a as I?
            # From probe: t.html single line gave Hi (h), T (j), a (I) all with same pattern (full line)
            # Pattern is full line escaped.
            # We'll implement: find <title>(.*?)</title> -> j, find <h[1-6][^>]*>(.*?)</h -> h, find id="..." -> I
            pat=make_pattern(line)
            for m in re.finditer(r'<title[^>]*>(.*?)</title>', line, re.IGNORECASE):
                name=m.group(1).strip()
                if name:
                    tags.append({"name":name,"file":path,"line":lineno,"pattern":pat,"kind":"j","scope":None,"scopeKind":None,"typeref":None,"fileScope":False,"lang":"HTML"})
            for m in re.finditer(r'<h[1-6][^>]*>(.*?)</h[1-6]>', line, re.IGNORECASE):
                name=m.group(1).strip()
                # Remove inner tags?
                name=re.sub(r'<[^>]+>', '', name).strip()
                if name:
                    tags.append({"name":name,"file":path,"line":lineno,"pattern":pat,"kind":"h","scope":None,"scopeKind":None,"typeref":None,"fileScope":False,"lang":"HTML"})
            for m in re.finditer(r'id\s*=\s*"([^"]+)"', line):
                name=m.group(1)
                tags.append({"name":name,"file":path,"line":lineno,"pattern":pat,"kind":"I","scope":None,"scopeKind":None,"typeref":None,"fileScope":False,"lang":"HTML"})
        return tags
    if lang == "JSON":
        tags=[]
        for idx, raw in enumerate(lines):
            lineno=idx+1
            line=raw.rstrip("\r\n")
            # Simplified: find "key": -> n? and nested? From probe: {"a":1,"b":{"c":2}} gave a (n), b (o), c (n object:b)
            # Rules: if value is object {} -> o? else n? Need to handle.
            # For simplicity, parse all "NAME": VALUE where VALUE starts with { -> o, else n, with scope if nested?
            # Track nesting via braces? For single line, b's value is {..} so o, a's value 1 so n, c's value 2 so n with scope b?
            # We'll implement: find all keys, determine if value is '{' -> o else n, and if inside object, scope is parent key?
            # For the test line, keys in order: a,b,c. b is object, c inside b.
            # Simple heuristic: if line contains '"b": {' then b is o, and subsequent keys until matching } are scoped to b.
            # For general, we'll just emit all keys as n except those whose value is '{' as o, and for keys after an object start, set scope to last object?
            # This is fragile but for simple single-level test, works: emit a as n, b as o, c as n with scope b.
            pat=make_pattern(line)
            # Find keys with positions
            keys=[]
            for m in re.finditer(r'"([^"]+)"\s*:\s*(\{|\[|[^\s,\}]+)', line):
                kname=m.group(1)
                vstart=m.group(2)
                keys.append((kname, vstart, m.start()))
            # Determine object keys
            obj_keys=set()
            for (kname, vstart, pos) in keys:
                if vstart=="{":
                    obj_keys.add(kname)
            # For each key, determine scope: if key is inside an object, scope is the object key that encloses it?
            # Simplify: if there is an object key before it and no closing } between? For single line with one object, c is after b's {, so scope b.
            # We'll set: for keys after first object key, scope is that object key (if key itself is not object? Actually c is not object, so scope b. For b itself, no scope.)
            # General: track depth?
            # For now, handle the specific case: if len(keys)==3 and middle is object, then third scoped to middle.
            # More general: maintain stack of objects based on braces? Complex.
            # We'll implement simple: iterate keys in order, maintain object stack based on counting { and } in line up to key position?
            # Count braces before each key?
            # For line '{"a": 1, "b": {"c": 2}}': before a (pos0) depth 1 (one {), before b depth 1, before c depth 2. So c depth 2 -> inside b.
            # We can compute depth by counting { minus } before pos.
            for (kname, vstart, pos) in keys:
                prefix=line[:pos]
                depth = prefix.count("{") - prefix.count("}")
                # depth 1 means top level, depth 2 means nested once
                # If depth==1 -> no scope, if depth>1 -> scope is previous object key at depth-1?
                # Find enclosing object: last object key before this with depth < current depth?
                scope=None
                scopeKind=None
                kind="n"
                if vstart=="{":
                    kind="o"  # object? What about array? For "[": maybe a? But probe JSON kinds: n,o,a,s? Let's check listkinds_JSON: need to see. For now, { -> o, [ -> a, else n.
                elif vstart=="[":
                    kind="a"
                else:
                    # Check if value is number? Then s? But probe didn't show s. For {"a":1}, a was n (string?), not s. So numbers still n? Actually JSON kinds: need to check listkinds_JSON.txt
                    kind="n"
                if depth>1:
                    # Find last object key before pos
                    for (pk, pv, ppos) in reversed(keys):
                        if ppos < pos and pv=="{":
                            # Check if this object encloses? Simplify: take immediate previous object
                            scope=pk
                            scopeKind="object"
                            break
                tags.append({"name":kname,"file":path,"line":lineno,"pattern":pat,"kind":kind,"scope":scope,"scopeKind":scopeKind,"typeref":None,"fileScope":False,"lang":"JSON"})
        return tags
    # For others, empty
    return []

def parse_file_by_lang(path, lang, lines, pattern_limit=96):
    # pattern_limit passed? Actually make_pattern uses global limit; we'll set via global? For now use default 96, but caller will handle via config.
    if lang in ("C",):
        return parse_c_file(path, lines, lang)
    elif lang in ("C++","CUDA"):
        return parse_c_file(path, lines, lang)
    elif lang == "Python":
        return parse_python_file(path, lines)
    elif lang == "Java":
        return parse_java_file(path, lines)
    elif lang in ("JavaScript","TypeScript"):
        return parse_javascript_file(path, lines, lang)
    elif lang == "Go":
        return parse_go_file(path, lines)
    elif lang == "Rust":
        return parse_rust_file(path, lines)
    elif lang == "Ruby":
        return parse_ruby_file(path, lines)
    elif lang in ("Sh","Bats"):
        return parse_sh_file(path, lines)
    elif lang in ("HTML","JSON"):
        return parse_generic_fallback(path, lines, lang)
    else:
        # For CPreProcessor? Actually CPreProcessor is subparser? Ignore.
        return []

PYEOF
